import os, re, glob

# Build set of existing note "titles" (normalized: lowercase, spaces==hyphens, no .md)
def norm(s):
    s = s.strip()
    if s.endswith('.md'): s = s[:-3]
    s = s.replace('-', ' ')
    return s.lower().strip()

files = [f for f in glob.glob('**/*.md', recursive=True) if '.git' not in f]
existing = {}
for f in files:
    base = os.path.basename(f)
    existing[norm(base)] = f

link_re = re.compile(r'\[\[([^\]]*)\]\]')
broken = {}
for f in files:
    with open(f, encoding='utf-8', errors='replace') as fh:
        for i, line in enumerate(fh, 1):
            for m in link_re.finditer(line):
                target = m.group(1).strip()
                if not target:
                    continue
                # handle [[link|alias]] and [[link#anchor]]
                target_key = target.split('|')[0].split('#')[0].strip()
                if not target_key:
                    continue
                if norm(target_key) not in existing:
                    broken.setdefault(target, []).append(f"{f}:{i}")

print(f"Existing notes: {len(files)}")
print(f"Broken/dangling wikilinks: {len(broken)}\n")
for target in sorted(broken):
    locs = broken[target]
    print(f"[[{target}]]  ->  {len(locs)} ref(s): {', '.join(sorted(set(locs)))}")
EOF

